record VV(Map<String, Integer> c) {
    boolean descends(VV o) {
        return o.c().entrySet().stream()
            .allMatch(e -> c.getOrDefault(e.getKey(), 0) >= e.getValue());
    }
}
var v1 = new VV(Map.of("A", 2));
var v2 = new VV(Map.of("A", 1, "B", 1));
System.out.println(v1.descends(v2) + " " + v2.descends(v1));
